description:
{
  "image_category": "MARKING_AND_SIGNAL",
  "summary": "Hình ảnh minh họa bố trí vạch dừng xe (vạch liền) và vạch chỉ dẫn sắp đến chỗ có bố trí vạch đi bộ qua đường (hình thoi) trên đường, kèm theo các khoảng cách bố trí cụ thể.",
  "items": [
    {
      "identifier": "Vạch dừng xe (Vạch 7.1)",
      "visual_or_geometric_features": "Vạch kẻ ngang màu trắng, liền nét, chạy song song với tim đường. Hình ảnh minh họa vị trí đặt vạch này cách mép vạch người đi bộ qua đường một khoảng từ 1,5m đến 3,0m.",
      "meaning_or_specification": "Dùng để xác định vị trí dừng xe để chờ tín hiệu cho phép đi tiếp hoặc nhường đường cho người đi bộ. Vạch này kẻ ngang toàn bộ bề rộng đường của hướng xe chạy."
    },
    {
      "identifier": "Vạch chỉ dẫn sắp đến chỗ có bố trí vạch đi bộ qua đường (Vạch 7.6)",
      "visual_or_geometric_features": "Vạch kẻ dạng hình thoi màu trắng, được bố trí trên làn đường để báo hiệu phía trước có vạch đi bộ qua đường.",
      "meaning_or_specification": "Sử dụng để báo hiệu sắp đến chỗ có bố trí vạch đi bộ qua đường, đặc biệt ở giữa đoạn đường nối hai nút giao, nhằm cảnh báo người lái xe phải nhường đường cho người đi bộ."
    },
    {
      "identifier": "Khoảng cách bố trí",
      "visual_or_geometric_features": "Hình ảnh ghi chú các khoảng cách: 1,5m và 3,0m (giữa hai mũi tên chỉ vị trí vạch dừng xe và vạch người đi bộ), và 50m (khoảng cách giữa các cụm vạch chỉ dẫn hình thoi).",
      "meaning_or_specification": "Khoảng cách từ mép vạch dừng xe đến mép vạch người đi bộ qua đường nên từ 1,5m đến 3,0m. Các vạch chỉ dẫn hình thoi được bố trí cách nhau 50m dọc theo chiều dài đường."
    }
  ]
}
